function formStatus(form,text,kind='saved'){
 const el=form.querySelector('[data-save-status]');if(el){el.textContent=text;el.dataset.state=kind;}
}
function autosaveForm(form,report=false){
 if(!form?.matches('[data-autosave]'))return true;
 clearTimeout(autosaveTimer);
 const touched=[...form.querySelectorAll('[name][data-touched]')];
 if(!touched.length){if(report&&form.getAttribute('id')==='list-form'&&!form.elements.namedItem('name').value.trim()){form.elements.namedItem('name').reportValidity();return false;}return true;}
 let invalid=[],changed=false;
 const formId=form.getAttribute('id');
 if(formId==='settings-form'){
   const numeric=['utcOffset','aperture','focalLength','eyepiece','afov','finderFov','finderMagnitude','sqm','transparency'];
   for(const input of touched){
     if(input.matches('[data-coordinate-min]'))validateCoordinateInput(input);
     if(!input.checkValidity()){invalid.push(input);continue;}
     let value=input.value;
     if(input.name==='latitude'||input.name==='longitude')value=parseCoordinate(value,+input.dataset.coordinateMin,+input.dataset.coordinateMax);
     else if(numeric.includes(input.name))value=Number(value);
     else if(input.name==='place')value=value.trim();
     if(value!==state.settings[input.name]){state.settings[input.name]=value;changed=true;}
     if(['latitude','longitude','place'].includes(input.name)&&!state.settings.locationConfirmed){state.settings.locationConfirmed=true;changed=true;}
   }
 }else{
   for(const input of form.querySelectorAll('input,select,textarea')){if(input.matches('[name=observedAt]'))input.setCustomValidity('');if(!input.checkValidity())invalid.push(input);}
   const data=new FormData(form);
   if(formId==='observation-form'){
     const date=fromLocal(data.get('observedAt'),state.settings.utcOffset);
     if(!Number.isFinite(date.getTime())||date.getTime()>Date.now()+5*60000){const input=form.elements.namedItem('observedAt');input.setCustomValidity('Укажи прошедшее время. Для будущего наблюдения создай список.');invalid.push(input);}
     if(!invalid.length){const id=data.get('id')||uid(),existing=state.observations.find(o=>o.id===id);const record={...(existing?.excludedFromFound?{excludedFromFound:true}:{}),id,objectId:data.get('objectId'),outcome:data.get('outcome'),observedAt:date.toISOString(),aperture:+data.get('aperture'),sqm:+data.get('sqm'),eyepiece:+data.get('eyepiece'),place:String(data.get('place')).trim(),note:String(data.get('note')).trim()};if(existing)state.observations[state.observations.indexOf(existing)]=record;else state.observations.push(record);form.elements.namedItem('id').value=id;changed=true;}
   }else if(formId==='quick-note-form'){
     const record=state.observations.find(o=>o.id===data.get('observationId'));if(record&&!invalid.length){record.note=String(data.get('note')).trim();changed=true;}
   }else if(formId==='list-form'){
     const name=String(data.get('name')).trim();if(!name&&!invalid.length)invalid.push(form.elements.namedItem('name'));
     if(!invalid.length){const id=data.get('id')||uid(),existing=state.lists.find(l=>l.id===id),objectId=data.get('objectToAdd');if(existing){existing.name=name;if(existing.date!==data.get('date'))delete existing.schedule;existing.date=data.get('date');existing.notes=data.get('notes');}else state.lists.push({id,name,date:data.get('date')||'',notes:data.get('notes')||'',objectIds:objectId?[objectId]:[],createdAt:new Date().toISOString()});form.elements.namedItem('id').value=id;selectedList=id;changed=true;}
   }
 }
 if(changed){if(!persist()){formStatus(form,'Не удалось сохранить на устройстве','error');return false;}recompute();render();}
 for(const input of touched)if(!invalid.includes(input))delete input.dataset.touched;
 if(formId==='settings-form'){
   features.refreshOptics();
   document.getElementById('settings-summary-title').textContent=`${state.settings.aperture} / ${state.settings.focalLength} мм`;
   document.getElementById('settings-summary-meta').textContent=`SQM ${fmt(state.settings.sqm,2)} · ${state.settings.filter==='none'?'без фильтра':state.settings.filter==='uhc'?'UHC':'O III'}`;
 }
 if(invalid.length){formStatus(form,'Проверь введённое значение','error');if(report){const panel=invalid[0].closest('[role=tabpanel]');if(panel?.hidden)document.querySelector(`[aria-controls="${panel.id}"]`)?.click();invalid[0].reportValidity();}return false;}
 formStatus(form,'Все изменения сохранены');return true;
}
function queueAutosave(input,immediate=false){
 const form=input.closest('form[data-autosave]');if(!form||!input.name||input.type==='hidden'||input.type==='file')return;
 input.dataset.touched='true';if(input.matches('[data-coordinate-min]'))validateCoordinateInput(input);if(input.name==='observedAt')input.setCustomValidity('');
 formStatus(form,'Сохраняем…','pending');clearTimeout(autosaveTimer);
 if(immediate)autosaveForm(form);else autosaveTimer=setTimeout(()=>{if(form.isConnected)autosaveForm(form);},450);
}
