async function prepareOffline(){
  if(Capacitor.isNativePlatform()){offlineReady=true;const el=document.getElementById('offline-state');if(el)el.innerHTML='<span class="dot"></span>Встроенный офлайн-каталог';return;}
  if(!('serviceWorker'in navigator))return;
  try{
    const currentVersion=new URL(document.querySelector('script[type="module"]').src).searchParams.get('v');
    let controllerChanged=false;
    const reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});
    await navigator.serviceWorker.ready;
    const check=()=>{const worker=navigator.serviceWorker.controller||reg.active;worker?.postMessage({type:'CHECK_OFFLINE'});};
    navigator.serviceWorker.addEventListener('message',event=>{
      if(event.data?.type==='OFFLINE_READY'){
        offlineReady=!currentVersion||event.data.version==='deepsky-'+currentVersion;
        const el=document.getElementById('offline-state');
        if(el)el.innerHTML=offlineReady?'<span class="dot"></span>Доступно офлайн':'<span class="dot"></span>Офлайн: подготовка';
        if(controllerChanged&&currentVersion&&event.data.version&&event.data.version!=='deepsky-'+currentVersion)showUpdateBanner();
      }
      if(event.data?.type==='OFFLINE_FAILED'){
        const el=document.getElementById('offline-state');if(el)el.textContent='Офлайн ещё не готов';
      }
    });
    navigator.serviceWorker.addEventListener('controllerchange',()=>{controllerChanged=true;check();});
    check();
    navigator.storage?.persist?.().catch(()=>{});
  }catch{
    const el=document.getElementById('offline-state');if(el)el.textContent='Офлайн недоступен';
  }
}
