async function start(){try{const loaded=await Promise.all(['data/catalog.json','data/stars.json','assets/image-credits.json','data/details.json','data/sources.json','assets/survey-credits.json','assets/preview-credits.json','data/constellations.json','data/sky-stars.json'].map(async url=>{const r=await fetch(versionedUrl(url));if(!r.ok){if(url.endsWith('details.json')||url.endsWith('sources.json'))return {};throw new Error('Не загружен '+url);}return r.json();}));[catalog,stars,credits,details,sources]=loaded;credits={...loaded[5],...credits};previews=loaded[6];constellations=loaded[7];skyStars=loaded[8];catalog.forEach(o=>byId.set(o.id,o));if(!A||!catalog.length)throw new Error('Не удалось открыть астрономические данные.');recompute();render();prepareOffline();}catch(error){root.innerHTML=`<div class="content">${empty('Не удалось открыть атлас',e(error.message),'','')}</div>`;}}
